import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return [] for an empty grid []");
  it.todo("should kill a single live cell [(0,0)] with 0 neighbors → [] (Rule 1: underpopulation)");
  it.todo("should kill both cells of a pair [(0,1), (1,1)], each with 1 neighbor → [] (Rule 1: underpopulation)");
  it.todo("should keep a live cell with 2 neighbors alive: center (1,1) of [(0,0), (1,0), (2,0), (1,1)] survives (Rule 2: survival)");
  it.todo("should keep a live cell with 3 neighbors alive: center (1,1) of [(0,0), (1,0), (2,0), (1,2)] → next generation contains (1,1) (Rule 2: survival)");
  it.todo("should kill a live cell with 4 neighbors: center (1,1) of the 3x3 ring-with-center pattern dies (Rule 3: overpopulation)");
  it.todo("should revive a dead cell with exactly 3 neighbors: (1,1) with neighbors [(0,0), (1,0), (0,1)] becomes alive (Rule 4: reproduction)");
  it.todo("should transform [(0,0), (1,0), (0,1)] into [(0,0), (1,0), (0,1), (1,1)] (Rule 4 example: full block emerges)");
  it.todo("should leave the block [(0,0), (1,0), (0,1), (1,1)] unchanged (still life)");
  it.todo("should transform the vertical blinker [(0,0), (0,1), (0,2)] into the horizontal blinker [(-1,1), (0,1), (1,1)]");
  it.todo("should transform the horizontal blinker [(-1,1), (0,1), (1,1)] back into the vertical blinker [(0,0), (0,1), (0,2)] (oscillation period 2)");
  it.todo("should handle negative coordinates: blinker at [(-5,-5), (-5,-4), (-5,-3)] → [(-6,-4), (-5,-4), (-4,-4)]");
});

