export function nextGeneration(cells: Cell[]): Cell[] {
  const survivors = cells.filter((cell) => {
    const neighbors = countNeighbors(cell, cells);
    return neighbors === 2 || neighbors === 3;
  });
  const births = deadNeighborsOf(cells).filter(
    (cell) => countNeighbors(cell, cells) === 3,
  );
  return [...survivors, ...births];
}

function deadNeighborsOf(cells: Cell[]): Cell[] {
  const candidates = new Map<string, Cell>();
  for (const [x, y] of cells) {
    for (const dx of [-1, 0, 1]) {
      for (const dy of [-1, 0, 1]) {
        const candidate: Cell = [x + dx, y + dy];
        if (!isAlive(candidate, cells)) {
          candidates.set(keyOf(candidate), candidate);
        }
      }
    }
  }
  return [...candidates.values()];
}

function isAlive([x, y]: Cell, cells: Cell[]): boolean {
  return cells.some(([liveX, liveY]) => liveX === x && liveY === y);
}

function keyOf([x, y]: Cell): string {
  return `${x},${y}`;
}

